// Original curriculum for SQL School. Queries use the bundled SQLite sandbox.
// Every lesson starts from a fresh copy of the sample database.
const lesson = (id, title, source, query, summary, explanation, tip, goals, challenge, phase = 'result', level = 'beginner') => ({
  id, title, short: title, source, query, summary, explanation, tip, goals,
  minutes: level === 'advanced' ? 12 : level === 'intermediate' ? 10 : 8,
  level, concept: title, challenge,
  steps: [
    { label: 'The question', title: 'Start with a question', body: summary, callout: 'Decide what one row of your answer should represent before writing SQL.', query: `SELECT * FROM ${source};`, phase: 'question' },
    { label: 'The data', title: `Meet the ${source} table`, body: `These are the stored rows we will work with. A column describes one attribute; a row describes one record. The query below reads this table without changing it.`, callout: `Our starting point is ${source}. The answer may have a different shape from these input rows.`, query: `SELECT * FROM ${source};`, phase: 'source' },
    { label: 'The query', title, body: explanation, callout: tip, query, phase },
    { label: 'The result', title: 'Read the answer', body: `Run the query and inspect its column names and rows. ${goals[1]}. The result is computed from the sample database; it is not a screenshot or a hard-coded answer.`, callout: 'SQL describes the answer you want. The database chooses the physical work needed to produce it.', query, phase: 'result' },
    { label: 'Takeaway', title: 'Make the idea stick', body: `${goals.join('. ')}. Try the practice challenge to use this idea in a query of your own.`, callout: tip, query, phase: 'recap' }
  ]
});
const practice = (prompt, solution, starter = 'SELECT\n  -- your columns\nFROM products;') => ({ prompt, starter, solution });

const journey = lesson('query-journey', 'How a Query Works', 'products',
  'SELECT name, price\nFROM products\nWHERE price < 50;',
  'The shop has a whole catalog. You only want the names and prices of products that cost less than $50. Follow that question from a table to an answer.',
  'FROM identifies the input table. WHERE keeps rows whose price is less than 50. SELECT keeps just the name and price columns. The stored products are not changed.',
  'Think: find the table, keep the matching rows, choose the columns.',
  ['Read a table as rows and columns', 'Follow a filter from input rows to output rows', 'Distinguish a query result from stored data'],
  practice('Return the name and price of every product costing less than $50.', 'SELECT name, price FROM products WHERE price < 50;'));
journey.minutes = 10;
journey.steps = [
  { label: 'A question', title: 'Find something under $50', body: 'A customer is shopping on a budget. Our catalog has many products, but the answer only needs two details: the product name and its price.', callout: 'Start with the question, not the syntax.', query: 'SELECT * FROM products;', phase: 'question' },
  { label: 'The table', title: 'A little structure goes a long way', body: 'The products table gives every item a row. Its id identifies the record; name, category, and price describe it. The same columns exist for every row.', callout: 'A table is a collection of records with a consistent set of columns.', query: 'SELECT * FROM products;', phase: 'source' },
  { label: 'FROM', title: 'Choose where to look', body: 'FROM products names the source. SELECT * means all its columns, so this query lets us inspect the full catalog before narrowing the answer.', callout: 'The asterisk is useful for exploring. For application queries, choose the columns you actually need.', query: 'SELECT *\nFROM products;', phase: 'source' },
  { label: 'WHERE', title: 'Let the matching rows through', body: 'WHERE price < 50 checks the condition against each input row. A price of exactly 50 does not qualify. The other rows remain in the stored table; they are just absent from this answer.', callout: 'WHERE filters rows. It does not delete them.', query: 'SELECT *\nFROM products\nWHERE price < 50;', phase: 'filter' },
  { label: 'SELECT', title: 'Keep only what you need', body: 'SELECT name, price chooses two output columns. The id and category helped describe the stored product, but the customer does not need them in this particular result.', callout: 'Filtering changes which rows you see. Projection changes which columns you see.', query: 'SELECT name, price\nFROM products\nWHERE price < 50;', phase: 'project' },
  { label: 'The answer', title: 'One question, one result set', body: 'The result contains only products under $50, with one row per matching product and two columns. Change 50 to another budget in Query Lab and see the answer change.', callout: 'Without ORDER BY, do not rely on the order in which rows appear.', query: 'SELECT name, price\nFROM products\nWHERE price < 50;', phase: 'result' },
  { label: 'Recap', title: 'You just wrote your first query', body: 'FROM chooses the table. WHERE filters the records. SELECT chooses the columns in the answer. These three building blocks carry you surprisingly far.', callout: 'SQL is a way to describe a result, not a list of instructions for visiting every row.', query: 'SELECT name, price\nFROM products\nWHERE price < 50;', phase: 'recap' }
];

